class OpenShopMusicCategoryOrder100114Evaluator(BaseEvaluator):
    """Verify the exact durable state and event order of all three music orders."""

    @classmethod
    def _resolve_api_port(cls, controller: Any, preferred_port: int) -> tuple[int, dict[int, Any]]:
        """Select the OpenShop instance that owns this task's completed state.

        Electron can leave an older OpenShop instance listening on 4310 and start
        the visible instance on the next free port.  Probing localhost ports is
        read-only; prefer the unique instance whose session and exact benchmark
        trace match this task, then fall back to the unique logged-in instance so
        an incomplete run still produces a useful evaluator failure.
        """
        ports = [preferred_port, *[port for port in range(4310, 4320) if port != preferred_port]]
        probes: dict[int, Any] = {}
        exact_candidates: list[int] = []
        logged_in_candidates: list[int] = []
        for candidate in ports:
            try:
                session_payload = OpenShopApiEvaluator._fetch_json(
                    controller, "/api/session", port=candidate
                )
                benchmark_payload = OpenShopApiEvaluator._fetch_json(
                    controller, "/api/benchmark", port=candidate
                )
                session = dict(session_payload.get("session") or {})
                events = [dict(row or {}) for row in benchmark_payload.get("events") or []]
                logged_in = bool(session.get("loggedIn")) and str(
                    (session.get("user") or {}).get("phone") or ""
                ) == "13800138000"
                exact_trace = False
                if logged_in and len(events) == len(EXPECTED_EVENTS):
                    try:
                        _, indices = cls._find_sequence(events, EXPECTED_EVENTS)
                        exact_trace = len(indices) == len(events)
                    except AssertionError:
                        pass
                probes[candidate] = {
                    "reachable": True,
                    "logged_in": logged_in,
                    "event_count": len(events),
                    "exact_trace": exact_trace,
                }
                if logged_in:
                    logged_in_candidates.append(candidate)
                if exact_trace:
                    exact_candidates.append(candidate)
            except Exception as exc:
                probes[candidate] = {
                    "reachable": False,
                    "error": f"{type(exc).__name__}: {exc}",
                }

        if len(exact_candidates) == 1:
            return exact_candidates[0], probes
        if len(exact_candidates) > 1:
            raise RuntimeError(f"multiple OpenShop instances have the exact task trace: {exact_candidates}")
        if len(logged_in_candidates) == 1:
            return logged_in_candidates[0], probes
        if preferred_port in logged_in_candidates:
            return preferred_port, probes
        if logged_in_candidates:
            raise RuntimeError(f"multiple logged-in OpenShop instances are ambiguous: {logged_in_candidates}")
        return preferred_port, probes

    @staticmethod
    def _project_order(order: Mapping[str, Any]) -> dict[str, Any]:
        items: dict[str, Any] = {}
        for raw_item in order.get("items") or []:
            item = dict(raw_item or {})
            product = dict(item.get("product") or {})
            review = item.get("review")
            items[str(product.get("id") or "")] = {
                "title": str(product.get("title") or ""),
                "quantity": int(item.get("quantity") or 0),
                "selected_spec": str(item.get("selectedSpec") or ""),
                "rating": int((review or {}).get("rating") or 0) if review else None,
                "review": str((review or {}).get("review") or "") if review else None,
            }
        return {
            "id": str(order.get("id") or ""),
            "address": str((order.get("address") or {}).get("label") or ""),
            "payment": str((order.get("payment") or {}).get("label") or ""),
            "note": str(order.get("note") or ""),
            "status": str(order.get("status") or ""),
            "items": items,
        }

    @staticmethod
    def _find_sequence(
        events: list[Mapping[str, Any]], expected: list[Mapping[str, Any]]
    ) -> tuple[list[Mapping[str, Any]], list[int]]:
        cursor = 0
        matched: list[Mapping[str, Any]] = []
        indices: list[int] = []
        for wanted in expected:
            found = None
            for index in range(cursor, len(events)):
                event = dict(events[index] or {})
                if str(event.get("type") or "") != str(wanted.get("type") or ""):
                    continue
                matcher = dict(wanted.get("match") or {})
                if all(event.get(key) == value for key, value in matcher.items()):
                    found = event
                    indices.append(index)
                    cursor = index + 1
                    break
            if found is None:
                raise AssertionError(f"missing ordered event: {wanted}")
            matched.append(found)
        return matched, indices

    def evaluate(self, context: Mapping[str, Any]) -> EvalResult:
        controller = context.get("controller")
        if controller is None or not hasattr(controller, "run_python_script"):
            return EvalResult(status=EvalStatus.ERROR, message="controller.run_python_script is required")
        params = dict(context.get("params") or {})
        expected_ruleset = str(params.get("expected_ruleset_sha256") or "")
        if expected_ruleset != RULESET_SHA256:
            return EvalResult(
                status=EvalStatus.ERROR,
                message=f"ruleset binding mismatch: expected {RULESET_SHA256}, got {expected_ruleset}",
                metadata={"task_id": TASK_ID, "ruleset_sha256": RULESET_SHA256, "read_only": True},
            )
        preferred_port = int(params.get("port", 4310) or 4310)
        checks: list[dict[str, Any]] = []
        metadata: dict[str, Any] = {
            "task_id": TASK_ID,
            "instruction_sha256": INSTRUCTION_SHA256,
            "ruleset_sha256": RULESET_SHA256,
            "ruleset_spec": RULESET_SPEC,
            "checkpoint_specs": CHECKPOINT_SPECS,
            "source_state_mode": str(params.get("source_state_mode") or "fresh_clone_verified"),
            "read_only": True,
            "business_state_mutations": [],
            "checks": checks,
        }

        def exact(check_id: str, value_contract_id: str, expected: Any, actual: Any) -> None:
            passed = actual == expected
            checks.append(
                {
                    "check_id": check_id,
                    "value_contract_id": value_contract_id,
                    "match_mode": "SCALAR_EXACT" if not isinstance(expected, (dict, list)) else "ORDERED_EXACT",
                    "expected": expected,
                    "actual": actual,
                    "passed": passed,
                }
            )
            if not passed:
                raise AssertionError(f"{check_id}: expected {expected!r}, got {actual!r}")

        try:
            port, port_probes = self._resolve_api_port(controller, preferred_port)
            metadata["preferred_api_port"] = preferred_port
            metadata["resolved_api_port"] = port
            metadata["api_port_probes"] = port_probes
            session_payload = OpenShopApiEvaluator._fetch_json(controller, "/api/session", port=port)
            session = dict(session_payload.get("session") or {})
            exact("session.logged_in", "session_login_exact", True, bool(session.get("loggedIn")))
            exact("session.phone", "session_login_exact", "13800138000", str((session.get("user") or {}).get("phone") or ""))

            cart_payload = OpenShopApiEvaluator._fetch_json(controller, "/api/cart", port=port)
            orders_payload = OpenShopApiEvaluator._fetch_json(controller, "/api/orders", port=port)
            benchmark_payload = OpenShopApiEvaluator._fetch_json(controller, "/api/benchmark", port=port)
            orders = [self._project_order(dict(row or {})) for row in orders_payload.get("orders") or []]
            events = [dict(row or {}) for row in benchmark_payload.get("events") or []]

            exact("cart.empty", "final_cart_empty", 0, len(cart_payload.get("items") or []))
            exact("orders.at_least_three", "three_newest_orders_exact", True, len(orders) >= 3)

            bound_orders = [orders[2], orders[1], orders[0]]
            names = ["first", "second", "third"]
            for name, order, expected in zip(names, bound_orders, RULESET_SPEC["orders"]):
                projected = {key: order[key] for key in ("address", "payment", "note", "status", "items")}
                exact(f"{name}_order", f"{name}_order_exact", expected, projected)

            matched, indices = self._find_sequence(events, EXPECTED_EVENTS)
            exact("events.count", "ordered_business_events_exact", len(EXPECTED_EVENTS), len(events))
            unexpected = [event for i, event in enumerate(events) if i not in set(indices)]
            exact("events.unexpected", "ordered_business_events_exact", [], unexpected)

            event_groups = (
                ("first", bound_orders[0], matched[8], matched[9:10]),
                ("second", bound_orders[1], matched[17], matched[18:19]),
                ("third", bound_orders[2], matched[29], matched[30:31]),
            )
            for name, order, checkout, reviews in event_groups:
                order_id = order["id"]
                exact(f"{name}.checkout_order_id", f"{name}_order_event_binding", order_id, str(checkout.get("orderId") or ""))
                exact(
                    f"{name}.review_order_ids",
                    f"{name}_review_exact",
                    [order_id] * len(reviews),
                    [str(event.get("orderId") or "") for event in reviews],
                )

            metadata["current_state_evidence"] = {
                "session": session,
                "cart_item_count": len(cart_payload.get("items") or []),
                "orders_newest_first": orders,
                "matched_events": matched,
                "raw_events": events,
                "unexpected_events": unexpected,
            }
        except AssertionError as exc:
            metadata["failure_reason"] = str(exc)
            return EvalResult(status=EvalStatus.FAIL, message=str(exc), metadata=metadata)
        except Exception as exc:
            metadata["failure_reason"] = f"{type(exc).__name__}: {exc}"
            return EvalResult(status=EvalStatus.ERROR, message=metadata["failure_reason"], metadata=metadata)

        return EvalResult(
            status=EvalStatus.PASS,
            message="All exact three-stage OpenShop music-order checks passed",
            metadata=metadata,
        )
